if ! command -v ffmpeg >/dev/null; then sudo apt-get update -qq && sudo apt-get install -y -qq ffmpeg; fi
ffmpeg -version | head -1; date +%T 装ffmpeg完成
npm i puppeteer --silent --no-fund --no-audit; date +%T puppeteer就绪; npx puppeteer browsers list 2>/dev/null | head -3
node render.js . 30 frames
ls frames | wc -l; date +%T 打帧完成
ffmpeg -y -hide_banner -loglevel error -framerate 30 -i frames/f%06d.jpg -c:v libx264 -preset veryfast -crf 19 -pix_fmt yuv420p "$ROOT/out/demo-huawei.mp4"
ls -la "$ROOT/out"

